# How music-store/model was made: the untouched init output (chinook-generated) shaped with validated edits.
# Each edit loads the whole definition against the database and is undone if it breaks anything.
# Writes the result to the directory given (default: target/chinook/music-store), never over the committed one.
#
#   export CHINOOK_DB_PASSWORD=reader
#   sh samples/chinook/shape-music-store.sh [out-dir]        # add DRIVERS=<dir> for the PostgreSQL driver
set -eu

HERE=$(dirname "$0")
OUT=${1:-target/chinook/music-store}
JAR=${JAR:-$(ls target/eclipselink-mcp-server-*.jar | grep -v original | head -1)}

rm -rf "$OUT"
mkdir -p "$OUT"
cp -R "$HERE/chinook-generated/model" "$HERE/chinook-generated/eclipselink-mcp.yaml" "$OUT/"

edit() {
  java -jar "$JAR" edit --definition "$OUT" ${DRIVERS:+--drivers "$DRIVERS"} "$@"
}

# Every single-column key becomes id
for e in Album:albumId Artist:artistId Customer:customerId Employee:employeeId Genre:genreId Invoice:invoiceId \
         InvoiceLine:invoiceLineId MediaType:mediaTypeId Playlist:playlistId Track:trackId; do
  edit rename-attribute "${e%%:*}" "${e##*:}" id
done

# Names agents understand
edit rename-attribute Employee employee reportsTo
edit rename-attribute Employee employees directReports
edit rename-attribute Invoice invoiceLines lines
edit rename-attribute Playlist playlistTracks tracks

# Reverse one-to-manys nobody navigates (a genre's 1,297 tracks), and columns agents do not need
edit remove-attribute Genre tracks
edit remove-attribute MediaType tracks
edit remove-attribute Track invoiceLines
edit remove-attribute Track playlistTracks
edit remove-attribute Employee birthDate fax
edit remove-attribute Customer fax

# A playlist entry has no version: it is locked through its playlist
edit lock-through PlaylistTrack playlist

# Meaning that names do not carry
edit describe Artist "A recording artist or band"
edit describe Album "An album released by an artist, with its tracks"
edit describe Track "A track (song or video) that the store sells, on an album"
edit describe Track.milliseconds "Length of the track in milliseconds"
edit describe Track.bytes "Size of the track's file in bytes"
edit describe Track.unitPrice "Current price of one copy in USD; each invoice line keeps the price it was sold at"
edit describe Genre "A music genre, such as Rock or Jazz"
edit describe MediaType "The file format a track is sold in, such as MPEG audio or AAC"
edit describe Customer "A store customer with contact details and their support representative"
edit describe Customer.supportRep "The employee who supports this customer"
edit describe Employee "A store employee; sales support agents look after customers"
edit describe Employee.reportsTo "The employee's manager"
edit describe Employee.directReports "Employees who report to this one"
edit describe Employee.customers "Customers this employee supports"
edit describe Invoice "A purchase by a customer, with its lines. Invoices cannot be changed once issued."
edit describe Invoice.invoiceDate "When the purchase was made (no time zone)"
edit describe Invoice.total "Sum of quantity x unit price over the lines, in USD"
edit describe InvoiceLine "One track bought on an invoice, at the price it was sold at"
edit describe InvoiceLine.unitPrice "Price of one copy when it was sold, in USD"
edit describe Playlist "A named list of tracks"
edit describe Playlist.tracks "The tracks on the playlist"
edit describe PlaylistTrack "A track on a playlist"
edit describe PlaylistTrack.addedAt "When the track was added (empty for the original playlists)"
